import React, { useEffect, useState } from "react";
import TextArea from "antd/es/input/TextArea";
import { Switch, Tooltip } from "antd";
import apiClient from "../../../../../api/client";
import ContentIcons1 from "./ContentComponents/ContentIcons1";
import { commitFilterModuleSettingsPatch } from "./filterSettingsSnapshot";
import {
  CustomTextModuleIconLockedSection,
  canUseCustomTextModuleIcon,
} from "./shared/filterModuleTier";

const ModuleCustomTextFilterGeneral = (props) => {
  const pathUrl = tc_caf_ajax.plugin_path;
  const iconsUrl = `${pathUrl}admin/fa-icons/fontawesome-5.json`;
  const { rowindex, columnindex, moduleindex } = props.indexes;
  const modSettings =
    props.data[rowindex]?.data[columnindex]?.data[moduleindex]?.settings;

  const [text, setText] = useState(modSettings?.customText ?? "");
  const [showIcon, setShowIcon] = useState(modSettings?.icons?.visibility ?? false);
  const [iconsArray, setIconsArray] = useState("");

  useEffect(() => {
    setText(modSettings?.customText ?? "");
    setShowIcon(modSettings?.icons?.visibility ?? false);
  }, [props.data, rowindex, columnindex, moduleindex]);

  useEffect(() => {
    const fetchIcons = async () => {
      try {
        const response = await apiClient.get(iconsUrl);
        if (response.data) {
          setIconsArray(response.data);
        }
      } catch (error) {
        console.error("Error ", error);
      }
    };

    fetchIcons();
  }, [iconsUrl]);

  const onChangeText = (e) => {
    const value = e.target.value;
    setText(value);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (settings) => {
        settings.customText = value;
      },
    });
  };

  const handleShowIcon = (checked) => {
    if (!canUseCustomTextModuleIcon()) {
      return;
    }
    setShowIcon(checked);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (settings) => {
        const icons = { ...(settings.icons || {}) };
        icons.visibility = checked;
        if (!icons.position) {
          icons.position = "before-customtext";
        }
        if (!icons.type) {
          icons.type = "icon";
        }
        settings.icons = icons;
      },
    });
  };

  const showIconControls = canUseCustomTextModuleIcon() ? showIcon : true;

  return (
    <>
      <label className="setting-label-main">Custom Text</label>
      <div className="module-content-tab-row">
        <Tooltip
          classNames={{ root: "caf-builder-tooltip" }}
          placement="topLeft"
          title="Enter custom text or HTML content."
        >
          <label>Content</label>
        </Tooltip>
        <TextArea
          placeholder="Add your text here ...."
          onChange={onChangeText}
          value={text}
        />
      </div>

      <div className="caf-filter-label-inner-row">
        <CustomTextModuleIconLockedSection>
          <div className="module-content-tab-row caf-pad-20">
            <div className="module-content-tab-row caf-design-two-half">
              <Tooltip
                classNames={{ root: "caf-builder-tooltip" }}
                placement="topLeft"
                title="Enable or disable icon before/after custom text."
              >
                <label>Show Icon</label>
              </Tooltip>
              <Switch
                onChange={handleShowIcon}
                checked={canUseCustomTextModuleIcon() ? showIcon : true}
                disabled={!canUseCustomTextModuleIcon()}
              />
            </div>
            {showIconControls && (
              <div className="module-content-tab-row caf-pad-10">
                {canUseCustomTextModuleIcon() && iconsArray ? (
                  <ContentIcons1
                    title="Icons"
                    data={props.data}
                    indexes={props.indexes}
                    iconsArray={iconsArray}
                    onSettingChange={props.onSettingChange}
                    tab="customtext_icon"
                    type=""
                  />
                ) : (
                  <div className="caf-reset-icon-locked-placeholder">
                    <i className="fas fa-font" aria-hidden="true" />
                  </div>
                )}
              </div>
            )}
          </div>
        </CustomTextModuleIconLockedSection>
      </div>
    </>
  );
};

export default ModuleCustomTextFilterGeneral;
